INSERT INTO destinations (slug, name, location, description, best_wildlife, safari_types, starting_price, image_url) VALUES
 ('yala', 'Yala National Park', 'Southern Province', 'Sri Lanka''s most celebrated park and home to one of the highest leopard densities on Earth, where dry scrub meets lagoons and the Indian Ocean.', 'Leopard, Sloth Bear, Elephant, Crocodile', 'Morning, Evening, Full Day', 45.00, 'https://images.pexels.com/photos/10607669/pexels-photo-10607669.jpeg?auto=compress&cs=tinysrgb&w=1200'),
 ('udawalawe', 'Udawalawe National Park', 'Sabaragamuwa / Uva', 'Open grasslands around the Udawalawe reservoir make this the most reliable place in Asia to watch wild elephant herds up close.', 'Asian Elephant, Water Buffalo, Eagles', 'Morning, Half Day, Evening', 40.00, 'https://images.pexels.com/photos/16159453/pexels-photo-16159453.jpeg?auto=compress&cs=tinysrgb&w=1200'),
 ('minneriya', 'Minneriya National Park', 'North Central Province', 'Witness "The Gathering" — hundreds of elephants converging on the ancient Minneriya tank during the dry season.', 'Elephant Gathering, Spotted Deer, Peacock', 'Evening, Family', 42.00, 'https://images.pexels.com/photos/32782089/pexels-photo-32782089.jpeg?auto=compress&cs=tinysrgb&w=1200'),
 ('wilpattu', 'Wilpattu National Park', 'North Western Province', 'Sri Lanka''s largest and quietest park, dotted with natural lakes (villus) — a secluded realm of leopards and sloth bears.', 'Leopard, Sloth Bear, Spotted Deer', 'Half Day, Full Day, Private', 50.00, 'https://images.pexels.com/photos/39339595/pexels-photo-39339595.jpeg?auto=compress&cs=tinysrgb&w=1200'),
 ('bundala', 'Bundala National Park', 'Southern Province', 'A Ramsar wetland famous for migratory flamingos and over 200 bird species amongst lagoons and salt pans.', 'Flamingo, Painted Stork, Crocodile', 'Morning, Evening, Birding', 35.00, 'https://images.pexels.com/photos/36873007/pexels-photo-36873007.jpeg?auto=compress&cs=tinysrgb&w=1200'),
 ('kumana', 'Kumana National Park', 'Eastern Province', 'Remote eastern wilderness bordering Yala, with the spectacular Kumana bird sanctuary and mangrove-fringed lagoons.', 'Peacock, Leopard, Waterbirds', 'Full Day, Photography', 48.00, 'https://images.pexels.com/photos/37391961/pexels-photo-37391961.jpeg?auto=compress&cs=tinysrgb&w=1200');
INSERT INTO safari_packages (name, package_type, destination_id, duration_hours, start_time, max_guests, base_price, description, image_url) VALUES
 ('Yala Morning Safari', 'MORNING', 1, 4, '05:30', 6, 55.00, 'Enter the park at first light when leopards are most active and the jungle glows golden.', 'https://images.pexels.com/photos/17081253/pexels-photo-17081253.jpeg?auto=compress&cs=tinysrgb&w=1200'),
 ('Yala Evening Safari', 'EVENING', 1, 4, '14:30', 6, 50.00, 'Track elephants and leopards through the cooling afternoon and watch the sun set over the lagoons.', 'https://images.pexels.com/photos/39464990/pexels-photo-39464990.jpeg?auto=compress&cs=tinysrgb&w=1200'),
 ('Udawalawe Half Day Safari', 'HALF_DAY', 2, 5, '06:00', 6, 60.00, 'A relaxed half day amongst Udawalawe''s elephant herds, with a stop at the reservoir viewpoint.', 'https://images.pexels.com/photos/35671094/pexels-photo-35671094.jpeg?auto=compress&cs=tinysrgb&w=1200'),
 ('Yala Full Day Safari', 'FULL_DAY', 1, 12, '05:30', 6, 140.00, 'Sunrise to sunset in the wild, exploring deep blocks of Yala with a picnic lunch by the beach.', 'https://images.pexels.com/photos/10607669/pexels-photo-10607669.jpeg?auto=compress&cs=tinysrgb&w=1200'),
 ('Wilpattu Private Safari', 'PRIVATE', 4, 6, '06:00', 4, 180.00, 'An exclusive jeep and senior naturalist just for your party, through Wilpattu''s silent villus.', 'https://images.pexels.com/photos/16444284/pexels-photo-16444284.jpeg?auto=compress&cs=tinysrgb&w=1200'),
 ('Minneriya Family Safari', 'FAMILY', 3, 4, '14:00', 8, 95.00, 'A child-friendly safari to the great elephant gathering, with activity packs and snacks for little explorers.', 'https://images.pexels.com/photos/3551497/pexels-photo-3551497.jpeg?auto=compress&cs=tinysrgb&w=1200'),
 ('Kumana Photography Safari', 'PHOTOGRAPHY', 6, 8, '05:30', 4, 160.00, 'Golden-hour access, bean bags and a photographer-guide to capture birds and big game in Kumana.', 'https://images.pexels.com/photos/36606292/pexels-photo-36606292.jpeg?auto=compress&cs=tinysrgb&w=1200'),
 ('Bundala Bird Watching Morning', 'MORNING', 5, 4, '06:00', 6, 45.00, 'Lagoons alive with flamingos, storks and kingfishers — perfect for birders and nature lovers.', 'https://images.pexels.com/photos/36873007/pexels-photo-36873007.jpeg?auto=compress&cs=tinysrgb&w=1200');
